"""Repair published guide examples and replace editor notes with reader links."""
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]

def replace_paragraph(slug, marker, replacement):
    path = ROOT / 'guides' / slug / 'index.html'
    html = path.read_text()
    matches = list(re.finditer(r'<p>.*?</p>', html, re.S))
    found = [m for m in matches if marker in m.group(0)]
    assert len(found) == 1, (slug, marker, len(found))
    m = found[0]
    path.write_text(html[:m.start()] + '<p>' + replacement + '</p>' + html[m.end():])

